package com.gameaggregator.featureflagservice.application;import com.fasterxml.jackson.core.type.TypeReference;import com.fasterxml.jackson.databind.ObjectMapper;import com.gameaggregator.platform.core.common.exception.NotFoundException;import com.gameaggregator.featureflagservice.api.FeatureFlagDtos.*;import com.gameaggregator.featureflagservice.domain.*;import com.gameaggregator.featureflagservice.infrastructure.*;import java.nio.charset.StandardCharsets;import java.util.*;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;@Service @Transactional public class FeatureFlagService{final FeatureFlagRepository flags;final FeatureFlagOverrideRepository overrides;final FeatureFlagHistoryRepository history;final FeatureFlagCache cache;final ObjectMapper json;public FeatureFlagService(FeatureFlagRepository f,FeatureFlagOverrideRepository o,FeatureFlagHistoryRepository h,FeatureFlagCache c,ObjectMapper j){flags=f;overrides=o;history=h;cache=c;json=j;}public FeatureFlag create(Create r){var f=flags.save(new FeatureFlag(r.key(),r.description(),r.enabled(),r.rolloutPercentage(),write(r.clientTargets())));record(f,r.actorId(),"CREATE",null);cache.put(f);return f;}public FeatureFlag update(UUID id,Update r){var f=get(id);String before=write(f);f.description=r.description();f.enabled=r.enabled();f.killSwitch=r.killSwitch();f.rolloutPercentage=r.rolloutPercentage();f.clientTargetsJson=write(r.clientTargets());record(f,r.actorId(),r.killSwitch()?"KILL_SWITCH":"UPDATE",before);cache.put(f);return f;}public FeatureFlagOverride override(UUID id,OverrideRequest r){var f=get(id);var o=overrides.findByFlagIdAndScopeTypeAndScopeId(id,r.scopeType(),r.scopeId()).orElseGet(()->new FeatureFlagOverride(id,r.scopeType(),r.scopeId(),r.enabled(),r.rolloutPercentage()));o.enabled=r.enabled();o.rolloutPercentage=r.rolloutPercentage();overrides.save(o);record(f,r.actorId(),"OVERRIDE_"+r.scopeType(),null);return o;}public Evaluation evaluate(String key,UUID tenantId,UUID environmentId,UUID clientId){var f=flags.findByFlagKey(key).orElseThrow(()->new NotFoundException("FLAG_NOT_FOUND","Feature flag was not found"));if(f.killSwitch)return new Evaluation(key,false,"KILL_SWITCH");Set<UUID> targets=read(f.clientTargetsJson);if(clientId!=null&&targets.contains(clientId))return new Evaluation(key,true,"CLIENT_TARGET");var scoped=environmentId==null?Optional.<FeatureFlagOverride>empty():overrides.findByFlagIdAndScopeTypeAndScopeId(f.id,"ENVIRONMENT",environmentId);if(scoped.isEmpty()&&tenantId!=null)scoped=overrides.findByFlagIdAndScopeTypeAndScopeId(f.id,"TENANT",tenantId);boolean enabled=scoped.map(o->o.enabled).orElse(f.enabled);int pct=scoped.map(o->o.rolloutPercentage).orElse(f.rolloutPercentage);if(!enabled)return new Evaluation(key,false,scoped.isPresent()?"SCOPE_DISABLED":"GLOBAL_DISABLED");if(clientId==null)return new Evaluation(key,pct==100,"NO_CLIENT_CONTEXT");return new Evaluation(key,inRollout(key,clientId,pct),"PERCENTAGE_"+pct);}static boolean inRollout(String key,UUID clientId,int percentage){return Math.floorMod(Objects.hash(key,clientId),100)<percentage;}public List<FeatureFlag> list(){return flags.findAll();}public List<FeatureFlagHistory> history(UUID id){get(id);return history.findAllByFlagIdOrderByCreatedAtDesc(id);}public FeatureFlag get(UUID id){return flags.findById(id).orElseThrow(()->new NotFoundException("FLAG_NOT_FOUND","Feature flag was not found"));}private void record(FeatureFlag f,UUID actor,String action,String before){history.save(new FeatureFlagHistory(f.id,actor,action,before,write(f)));}private String write(Object o){try{return json.writeValueAsString(o==null?Set.of():o);}catch(Exception e){throw new IllegalArgumentException(e);}}private Set<UUID> read(String s){try{return json.readValue(s,new TypeReference<Set<UUID>>(){});}catch(Exception e){throw new IllegalStateException(e);}}}